from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v25r1, v24r3, v23r1
from .modals import StartDiagnosticCheckModal


class Diagnostic(v25r1.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._antenna_line_online_monitoring = AntennaLineOnlineMonitoring(driver, download_checker)
        self._diagnostic_check = DiagnosticCheckPage(driver)


class DiagnosticCheckPage(v24r3.diagnostic.DiagnosticCheckPage):

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)


class DiagnosticCheckPageViewPanel(v24r3.diagnostic.DiagnosticCheckPageViewPanel):

    _RADIO_OPTIONS = '//div[@aria-label="{}"]/following-sibling::ul/p-treenode/li/div'
    _TREEITEM = '//div[@aria-label="{}"]//button/span'

    def start_diagnostic_check(self, scope, timeout=60, **kwargs):
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)
        self.select_element_from_dropdown_list_by_text_and_click(scope,
                                                                 (By.XPATH, self._SCOPE_BUTTON),
                                                                 (By.XPATH, self._SCOPE_OPTION),
                                                                 timeout)
        self.wait_for_enable((By.XPATH, self._SCOPE_BUTTON), timeout)

        all_service_impact = None
        if self.FULL_DIAGNOSTIC_CHECK == scope:
            all_service_impact = kwargs.get('allow_service_impact', False)
            self.select_checkbox_by_specified_status(all_service_impact,
                                                     self._ALLOW_SERVICE_IMPACT + '//input',
                                                     self._ALLOW_SERVICE_IMPACT)

        elif self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope:
            bts_checkpoints = kwargs.get('bts_checkpoints', [])
            self._select_bts_checkpoints(bts_checkpoints, timeout)

            radio_checkpoints = kwargs.get('radio_checkpoints', [])
            self.rst = False
            self._select_radio_checkpoints(radio_checkpoints, timeout)

        self.click_enabled_element((By.XPATH, self._START_BUTTON), timeout)

        if self.FULL_DIAGNOSTIC_CHECK == scope and all_service_impact:
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(timeout)
            check_modal.start()
            self.wait_for_visibility(self._STARTING_STATUS, timeout)
            return

        if self.CUSTOMIZED_DIAGNOSTIC_CHECK == scope and (not radio_checkpoints or self.rst):
            check_modal = StartDiagnosticCheckModal(self.driver)
            check_modal.wait_until_diagnostic_check_modal_appear(timeout)
            check_modal.start()

        self.wait_for_visibility(self._STARTING_STATUS, timeout)
        self.wait_for_invisibility(self._STARTING_STATUS, timeout)
        self.wait_for_visibility(self._START_SUCCEEDED_STATUS, timeout)
        return self.get_text_by_xpath(self._START_SUCCEEDED_STATUS)

    def _select_radio_checkpoints_by_input(self, radio_checkpoints, timeout=60):  # noqa: C901
        radio_titles = [elem.text.strip() for elem in self.driver.find_elements_by_xpath(self._RADIO_TITLES)]
        rmods = list(radio_checkpoints.keys())

        for radio_title in radio_titles:
            if radio_title not in rmods:
                radio_checkpoints[radio_title] = []

        for rmod_name, checkpoint in radio_checkpoints.items():
            for check in checkpoint:
                if "(RST)" in check:
                    self.rst = True
            tree_item_xpath = self._TREEITEM.format(rmod_name)
            expand_status = "pi-chevron-down" in self._get_element_attribute_by_xpath(tree_item_xpath, "class")
            if not expand_status:
                self.click_enabled_element((By.XPATH, tree_item_xpath), timeout)
            self._choose_value_if_checkbox_exist(self._RADIO_OPTIONS.format(rmod_name),
                                                 checkpoint,
                                                 'aria-checked')

            self.driver.execute_script('arguments[0].click();', self.driver.find_element_by_xpath(tree_item_xpath))

    def _choose_value_if_checkbox_exist(self, check_box_xpath, value, attribute):
        value = [str(item) for item in value]
        for index, _ in enumerate(self.driver.find_elements_by_xpath(check_box_xpath)):
            self._scroll_elem_into_view(self.driver.find_elements_by_xpath(check_box_xpath)[index])
            is_checked = self._get_element_attribute_by_xpath(check_box_xpath + r"/div", attribute, index) == "true"
            element_text = self._get_element_attribute_by_xpath(check_box_xpath, "aria-label", index)
            if (not is_checked and element_text in value) or (is_checked and element_text not in value):
                self._click_element_by_multiple_xpath_and_index(
                    [check_box_xpath, './/div[contains(@class, "p-checkbox-box")]'],
                    [index, 0]
                )


class AntennaLineOnlineMonitoring(v23r1.diagnostic.AntennaLineOnlineMonitoring):

    def __init__(self, driver, download_checker):
        super(AntennaLineOnlineMonitoring, self).__init__(driver, download_checker)
        self._view_panel = AntennaLineOnlineMonitoringViewPanel(driver, download_checker)


class AntennaLineOnlineMonitoringViewPanel(v23r1.diagnostic.AntennaLineOnlineMonitoringViewPanel):

    def _final_deal_with_info(self, info):
        new_info = []
        for line in info:
            line_keys = list(line.keys())
            line_values = list(line.values())
            try:
                index = line_values.index(list(filter(lambda x: '\n' in x, line_values))[0])
                item_num = len(line_values[index].split("\n"))
                for i in range(item_num):
                    new_values = line_values[:index] + [item.split("\n")[i] for item in line_values[index:]]
                    new_info.append(dict(zip(line_keys, new_values)))
            except IndexError:
                pass
        return new_info if new_info else info
